exports.latestData = [
    { "id": "15028", "nameEn": "Flower of Paradise Lost", "nameVi": "Đóa Hoa Trang Viên Thất Lạc", "rarityList": [4, 5], "piece2DescEn": "Increases Elemental Mastery by 80.", "piece2DescVi": "Tăng 80 điểm Tinh Thông Nguyên Tố.", "piece4DescEn": "The equipping character's Bloom, Hyperbloom, and Burgeon reaction DMG are increased by 40%, and their Lunar-Bloom reaction DMG is increased by 10%. Additionally, after the equipping character triggers Bloom, Hyperbloom, Lunar-Bloom, or Burgeon, they will gain another 25% bonus to the effects mentioned prior. Each stack of this lasts 10s. Max 4 stacks simultaneously. This effect can only be triggered once per second. The character who equips this can still trigger its effects when not on the field.", "piece4DescVi": "Người trang bị tăng 40% sát thương gây ra từ phản ứng Sum Suê, Nở Rộ, Bung Tỏa, tăng 10% sát thương gây ra từ phản ứng Nguyệt-Sum Suê. Ngoài ra, người trang bị sau khi kích hoạt phản ứng Sum Suê, Nở Rộ, Bung Tỏa, Nguyệt-Sum Suê sẽ tăng 25% hiệu ứng nêu trên, duy trì 10s, tối đa cộng dồn 4 lần, mỗi 1s tối đa kích hoạt một lần. Người trang bị khi không ra trận vẫn có thể kích hoạt hiệu quả này.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15028_4.webp" },
    { "id": "15029", "nameEn": "Nymph's Dream", "nameVi": "Giấc Mộng Thủy Tiên", "rarityList": [4, 5], "piece2DescEn": "Hydro DMG Bonus +15%", "piece2DescVi": "Nhận 15% buff sát thương nguyên tố Thủy.", "piece4DescEn": "After Normal, Charged, and Plunging Attacks, Elemental Skills, and Elemental Bursts hit opponents, 1 stack of Mirrored Nymph will be triggered, lasting 8s. When under the effect of 1, 2, or 3 or more Mirrored Nymph stacks, ATK will be increased by 7%/16%/25%, and Hydro DMG Bonus will be increased by 4%/9%/15%. Mirrored Nymph stacks created by Normal, Charged, and Plunging Attacks, Elemental Skills, and Elemental Bursts exist independently.", "piece4DescVi": "Tấn Công Thường, Trọng Kích, Tấn Công Khi Đáp, Kỹ Năng Nguyên Tố hoặc Kỹ Năng Nộ sau khi trúng kẻ địch sẽ sản sinh 1 tầng \"Thủy Tiên Trong Kính\" duy trì 8s. Khi \"Thủy Tiên Trong Kính\" đạt 1/2/3 tầng và trở lên, tấn công tăng 7%/16%/25%, Sát Thương Nguyên Tố Thủy tăng 4%/9%/15%. Hiệu quả \"Thủy Tiên Trong Kính\" sản sinh từ Tấn Công Thường, Trọng Kích, Tấn Công Khi Đáp, Kỹ Năng Nguyên Tố hoặc Kỹ Năng Nộ sẽ tồn tại độc lập nhau.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15029_4.webp" },
    { "id": "15030", "nameEn": "Vourukasha's Glow", "nameVi": "Vầng Sáng Vourukasha", "rarityList": [4, 5], "piece2DescEn": "HP +20%", "piece2DescVi": "HP tăng 20%", "piece4DescEn": "Elemental Skill and Elemental Burst DMG will be increased by 10%. After the equipping character takes DMG, the aforementioned DMG Bonus is increased by 80% for 5s. This effect increase can have 5 stacks. The duration of each stack is counted independently. These effects can be triggered even when the equipping character is not on the field.", "piece4DescVi": "Sát thương gây ra từ Kỹ Năng Nguyên Tố và Kỹ Năng Nộ tăng 10%. Trong 5s sau khi người trang bị chịu sát thương, hiệu quả tăng sát thương nêu trên tăng 80%, lượng tăng thêm này tối đa cộng dồn 5 tầng, mỗi tầng tính thời gian độc lập nhau. Nhân vật không ra trận cũng có thể kích hoạt hiệu quả này.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15030_4.webp" },
    { "id": "15031", "nameEn": "Marechaussee Hunter", "nameVi": "Thợ Săn Marechaussee", "rarityList": [4, 5], "piece2DescEn": "Normal and Charged Attack DMG +15%", "piece2DescVi": "Tăng 15% sát thương tấn công thường và trọng kích.", "piece4DescEn": "When current HP increases or decreases, CRIT Rate will be increased by 12% for 5s. Max 3 stacks.", "piece4DescVi": "Khi HP hiện tại có tăng hoặc giảm, tỉ lệ bạo kích tăng 12%. Hiệu quả này duy trì 5s, tối đa cộng dồn 3 lần.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15031_4.webp" },
    { "id": "15032", "nameEn": "Golden Troupe", "nameVi": "Đoàn Kịch Hoàng Kim", "rarityList": [4, 5], "piece2DescEn": "Increases Elemental Skill DMG by 20%.", "piece2DescVi": "Sát thương Kỹ Năng Nguyên Tố gây ra tăng 20%.", "piece4DescEn": "Increases Elemental Skill DMG by 25%. Additionally, when not on the field, Elemental Skill DMG will be further increased by 25%. This effect will be cleared 2s after taking the field.", "piece4DescVi": "Sát thương Kỹ Năng Nguyên Tố gây ra tăng 25%; Ngoài ra, khi không ra trận, sát thương Kỹ Năng Nguyên Tố gây ra tăng thêm 25%. Hiệu quả này sẽ xóa sau khi ra trận 2s.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15032_4.webp" },
    { "id": "15033", "nameEn": "Song of Days Past", "nameVi": "Khúc Ca Ngày Cũ", "rarityList": [4, 5], "piece2DescEn": "Healing Bonus +15%.", "piece2DescVi": "Tăng Trị Liệu lên 15%.", "piece4DescEn": "When the equipping character heals a party member, the Yearning effect will be created for 6s, which records the total amount of healing provided (including overflow healing). When the duration expires, the Yearning effect will be transformed into the \"Waves of Days Past\" effect: When your active party member hits an opponent with a Normal Attack, Charged Attack, Plunging Attack, Elemental Skill, or Elemental Burst, the DMG dealt will be increased by 8% of the total healing amount recorded by the Yearning effect. The \"Waves of Days Past\" effect is removed after it has taken effect 5 times or after 10s. A single instance of the Yearning effect can record up to 15,000 healing, and only a single instance can exist at once, but it can record the healing from multiple equipping characters. Equipping characters on standby can still trigger this effect.", "piece4DescVi": "Người trang bị khi trị liệu cho nhân vật trong đội, sẽ sản sinh hiệu quả \"Mong Mỏi\" trong 6s, ghi nhận lượng HP hồi phục khi trị liệu (Bao gồm phần dư ra). Khi thời gian duy trì kết thúc, hiệu quả \"Mong Mỏi\" sẽ chuyển thành hiệu quả \"Làn Sóng Ngày Cũ\": Khi Tấn Công Thường, Trọng Kích, Tấn Công Khi Đáp, Kỹ Năng Nguyên Tố hoặc Kỹ Năng Nộ của nhân vật ra trận trong đội bản thân trúng kẻ địch, sát thương gây ra sẽ tăng dựa vào 8% lượng HP hồi phục được ghi nhận trong hiệu quả \"Mong Mỏi\". Hiệu quả \"Làn Sóng Ngày Cũ\" sẽ xóa khi hiệu lực 5 lần hoặc sau 10s. Một lần hiệu quả \"Mong Mỏi\" tối đa ghi nhớ 15000 điểm hồi phục, tối đa tồn tại một hiệu quả cùng lúc, nhưng có thể ghi nhận lượng hồi phục của nhiều người trang bị. Người trang bị không ra trận cũng có thể kích hoạt hiệu quả.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15033_4.webp" },
    { "id": "15034", "nameEn": "Nighttime Whispers in the Echoing Woods", "nameVi": "Tiếng Đêm Trong Rừng Vang", "rarityList": [4, 5], "piece2DescEn": "ATK +18%.", "piece2DescVi": "Tấn công tăng 18%", "piece4DescEn": "After using an Elemental Skill, gain a 20% Geo DMG Bonus for 10s. When under a shield granted by the Crystallize reaction, or when Moondrifts formed by Lunar-Crystallize reactions are nearby, the above effect is increased by 150%. When these conditions are no longer met, this additional increase disappears after 1s.", "piece4DescVi": "Trong 10s sau khi thi triển Kỹ Năng Nguyên Tố, nhận 20% buff Sát Thương Nguyên Tố Nham. Nếu được khiên sinh ra từ phản ứng Kết Tinh bảo vệ, hoặc xung quanh có Trăng Trôi sinh ra từ phản ứng Nguyệt-Kết Tinh, hiệu quả trên sẽ gia tăng 150%. Hiệu quả tăng thêm này sẽ xóa sau 1s khi không thỏa mãn điều kiện nêu trên.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15034_4.webp" },
    { "id": "15035", "nameEn": "Fragment of Harmonic Whimsy", "nameVi": "Mảnh Hài Hòa Bất Thường", "rarityList": [4, 5], "piece2DescEn": "ATK +18%.", "piece2DescVi": "Tấn công tăng 18%", "piece4DescEn": "When the value of a Bond of Life increases or decreases, this character deals 18% increased DMG for 6s. Max 3 stacks.", "piece4DescVi": "Khi giá trị Khế Ước Sinh Mệnh tăng hoặc giảm, sát thương nhân vật gây ra sẽ tăng 18% trong 6s. Tối đa cộng dồn 3 lần.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15035_4.webp" },
    { "id": "15036", "nameEn": "Unfinished Reverie", "nameVi": "Ảo Mộng Chưa Hoàn Thành", "rarityList": [4, 5], "piece2DescEn": "ATK +18%.", "piece2DescVi": "Tấn công tăng 18%", "piece4DescEn": "After leaving combat for 3s, DMG dealt increased by 50%. In combat, if no Burning opponents are nearby for more than 6s, this DMG Bonus will decrease by 10% per second until it reaches 0%. When a Burning opponent exists, it will increase by 10% instead until it reaches 50%. This effect still triggers if the equipping character is off-field.", "piece4DescVi": "Sau khi rời khỏi chiến đấu 3s, sát thương gây ra tăng 50%. Khi trong trạng thái chiến đấu, nếu trên 6s mà xung quanh không có kẻ địch bị trạng thái Thiêu Đốt, thì hiệu quả tăng sát thương nêu trên sẽ giảm 10% mỗi giây cho đến khi giảm còn 0%; Nếu có kẻ địch bị trạng thái Thiêu Đốt thì mỗi giây sẽ tăng 10% cho đến khi tăng đến 50%. Nhân vật trang bị Thánh Di Vật này khi không ra trận vẫn có thể kích hoạt hiệu quả này.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15036_4.webp" },
    { "id": "15037", "nameEn": "Scroll of the Hero of Cinder City", "nameVi": "Bức Tranh Dũng Sĩ Thành Tro Tàn", "rarityList": [4, 5], "piece2DescEn": "When a nearby party member triggers a Nightsoul Burst, the equipping character regenerates 6 Elemental Energy.", "piece2DescVi": "Khi nhân vật trong đội gần đó kích hoạt Dạ Hồn Bùng Nổ, người trang bị sẽ hồi phục 6 điểm Năng Lượng Nguyên Tố.", "piece4DescEn": "After the equipping character triggers a reaction related to their Elemental Type, all nearby party members gain a 12% Elemental DMG Bonus for the Elemental Types involved in the elemental reaction for 15s. If the equipping character is in the Nightsoul's Blessing state when triggering this effect, all nearby party members gain an additional 28% Elemental DMG Bonus for the Elemental Types involved in the elemental reaction for 20s. The equipping character can trigger this effect while off-field, and the DMG bonus from Artifact Sets with the same name do not stack.", "piece4DescVi": "Sau khi người trang bị kích hoạt phản ứng liên quan đến loại nguyên tố của họ, tất cả nhân vật trong đội ở gần tăng 12% buff Sát Thương Nguyên Tố của loại nguyên tố liên quan đến phản ứng đó, duy trì 15s. Nếu người trang bị đang trong trạng thái Dạ Hồn Chúc Phúc khi kích hoạt hiệu quả này, sẽ còn khiến tất cả nhân vật trong đội ở gần tăng thêm 28% buff Sát Thương Nguyên Tố của loại nguyên tố liên quan đến phản ứng đó, duy trì 20s. Người trang bị khi không ra trận cũng có thể kích hoạt hiệu quả nêu trên. Hiệu quả sát thương tăng thêm sản sinh từ bộ Thánh Di Vật cùng tên sẽ không thể cộng dồn.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15037_4.webp" },
    { "id": "15038", "nameEn": "Obsidian Codex", "nameVi": "Bí Điển Obsidian", "rarityList": [4, 5], "piece2DescEn": "While the equipping character is in Nightsoul's Blessing and is on the field, their DMG dealt is increased by 15%.", "piece2DescVi": "Khi người trang bị ở trạng thái Dạ Hồn Chúc Phúc và đang ra trận, sát thương gây ra tăng 15%.", "piece4DescEn": "After the equipping character consumes 1 Nightsoul point while on the field, CRIT Rate increases by 40% for 6s. This effect can trigger once every second.", "piece4DescVi": "Người trang bị sau khi tiêu hao 1 điểm Dạ Hồn trong trận, Tỷ Lệ Bạo Kích tăng 40% trong 6s. Hiệu quả này mỗi 1s tối đa kích hoạt một lần.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15038_4.webp" },
    { "id": "15039", "nameEn": "Long Night's Oath", "nameVi": "Lời Thề Đêm Dài", "rarityList": [4, 5], "piece2DescEn": "Plunging Attack DMG increased by 25%.", "piece2DescVi": "Tăng 25% sát thương Tấn Công Khi Đáp.", "piece4DescEn": "After the equipping character's Plunging Attack/Charged Attack/Elemental Skill hits an opponent, they will gain 1/2/2 stack(s) of \"Radiance Everlasting.\" Plunging Attacks, Charged Attacks, or Elemental Skills can each trigger this effect once every 1s. Radiance Everlasting: Plunging Attacks deal 15% increased DMG for 6s. Max 5 stacks. Each stack's duration is counted independently.", "piece4DescVi": "Sau khi đòn Tấn Công Khi Đáp/Trọng Kích/Kỹ Năng Nguyên Tố của người trang bị đánh trúng kẻ địch, sẽ nhận được 1/2/2 tầng \"Rạng Rỡ Vĩnh Cửu\". Tấn Công Khi Đáp, Trọng Kích hoặc Kỹ Năng Nguyên Tố mỗi 1s tối đa kích hoạt riêng biệt hiệu quả này một lần. Rạng Rỡ Vĩnh Cửu: Tăng 15% sát thương Tấn Công Khi Đáp trong 6s, tối đa cộng dồn 5 tầng, mỗi tầng tính giờ riêng.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15039_4.webp" },
    { "id": "15040", "nameEn": "Finale of the Deep Galleries", "nameVi": "Đoạn Kết Hành Lang Sâu", "rarityList": [4, 5], "piece2DescEn": "Cryo DMG Bonus +15%", "piece2DescVi": "Tăng sát thương nguyên tố Băng 15%", "piece4DescEn": "When the equipping character has 0 Elemental Energy, Normal Attack DMG is increased by 60% and Elemental Burst DMG is increased by 60%. After the equipping character deals Normal Attack DMG, the aforementioned Elemental Burst effect will stop applying for 6s. After the equipping character deals Elemental Burst DMG, the aforementioned Normal Attack effect will stop applying for 6s. This effect can trigger even if the equipping character is off the field.", "piece4DescVi": "Khi Năng Lượng Nguyên Tố của người trang bị bằng 0, tăng 60% sát thương Tấn Công Thường, tăng 60% sát thương Kỹ Năng Nộ. Sau khi người trang bị gây sát thương Tấn Công Thường, hiệu quả tăng sát thương Kỹ Năng Nộ nêu trên sẽ mất hiệu lực trong 6s. Sau khi người trang bị gây sát thương Kỹ Năng Nộ, hiệu quả tăng sát thương Tấn Công Thường nêu trên sẽ mất hiệu lực trong 6s. Nhân vật đang dự bị cũng có thể kích hoạt hiệu quả này.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15040_4.webp" },
    { "id": "15041", "nameEn": "Night of the Sky's Unveiling", "nameVi": "Đêm Trời Hé Lộ", "rarityList": [4, 5], "piece2DescEn": "Increases Elemental Mastery by 80.", "piece2DescVi": "Tăng 80 điểm Tinh Thông Nguyên Tố.", "piece4DescEn": "When nearby party members trigger Lunar Reactions, if the equipping character is on the field, gain the Gleaming Moon: Intent effect for 4s: Increases CRIT Rate by 15%/30% when the party's Moonsign is Nascent Gleam/Ascendant Gleam. All party members' Lunar Reaction DMG is increased by 10% for each different Gleaming Moon effect that party members have. Effects from Gleaming Moon cannot stack.", "piece4DescVi": "Khi nhân vật trong đội ở gần kích hoạt phản ứng Nguyệt, nếu người trang bị trong trận, sẽ nhận được hiệu quả \"Trăng Sáng - Ý Niệm\" trong 4s: Khi Nguyệt Triệu của đội là Hé Sáng/Rực Sáng, sẽ tăng 15%/30% Tỷ Lệ Bạo Kích. Với mỗi hiệu quả \"Trăng Sáng\" khác nhau mà nhân vật trong đội sở hữu, tất cả nhân vật trong đội sẽ tăng 10% sát thương phản ứng Nguyệt. Hiệu quả sản sinh từ \"Trăng Sáng\" sẽ không thể cộng dồn.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15041_4.webp" },
    { "id": "15042", "nameEn": "Silken Moon's Serenade", "nameVi": "Khúc Ca Trăng Lụa", "rarityList": [4, 5], "piece2DescEn": "Energy Recharge +20%.", "piece2DescVi": "Hiệu Quả Nạp Nguyên Tố tăng 20%.", "piece4DescEn": "When dealing Elemental DMG, gain the Gleaming Moon: Devotion effect for 8s: Increases all party members' Elemental Mastery by 60/120 when the party's Moonsign is Nascent Gleam/Ascendant Gleam. The equipping character can trigger this effect while off-field. All party members' Lunar Reaction DMG is increased by 10% for each different Gleaming Moon effect that party members have. Effects from Gleaming Moon cannot stack.", "piece4DescVi": "Khi gây sát thương nguyên tố, sẽ nhận hiệu quả \"Trăng Sáng - Tín Ngưỡng\" trong 8s: Khi Nguyệt Triệu của đội là Hé Sáng/Rực Sáng, tất cả nhân vật trong đội sẽ tăng 60/120 điểm Tinh Thông Nguyên Tố. Người trang bị không ra trận cũng có thể kích hoạt hiệu quả nêu trên. Với mỗi hiệu quả \"Trăng Sáng\" khác nhau mà nhân vật trong đội sở hữu, tất cả nhân vật trong đội sẽ tăng 10% sát thương phản ứng Nguyệt. Hiệu quả sản sinh từ \"Trăng Sáng\" sẽ không thể cộng dồn.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15042_4.webp" },
    { "id": "15043", "nameEn": "Aubade of Morningstar and Moon", "nameVi": "Khúc Ca Của Trăng Và Sao Mai", "rarityList": [4, 5], "piece2DescEn": "Increases Elemental Mastery by 80.", "piece2DescVi": "Tăng 80 điểm Tinh Thông Nguyên Tố.", "piece4DescEn": "When the equipping character is off-field, Lunar Reaction DMG is increased by 20%. When the party's Moonsign Level is at least Ascendant Gleam, Lunar Reaction DMG will be further increased by 40%. This effect will disappear after the equipping character is active for 3s.", "piece4DescVi": "Khi người trang bị đang dự bị, sát thương phản ứng Nguyệt gây ra tăng 20%. Khi Nguyệt Triệu của đội tối thiểu là Rực Sáng, sát thương phản ứng Nguyệt tăng thêm 40%. Hiệu quả trên sẽ bị xóa sau 3s từ khi người trang bị ra trận.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15043_4.webp" },
    { "id": "15044", "nameEn": "A Day Carved From Rising Winds", "nameVi": "Ngày Nổi Gió", "rarityList": [4, 5], "piece2DescEn": "ATK +18%.", "piece2DescVi": "Tấn công tăng 18%.", "piece4DescEn": "After a Normal Attack, Charged Attack, Elemental Skill, or Elemental Burst hits an opponent, gain the Blessing of Pastoral Winds effect for 6s: ATK is increased by 25%. If the equipping character has completed Witch's Homework, Blessing of Pastoral Winds will be upgraded to Resolve of Pastoral Winds, which additionally increases the CRIT Rate of the equipping character by 20%. This effect can be triggered even when the character is off-field.", "piece4DescVi": "Sau khi Tấn Công Thường, Trọng Kích, Kỹ Năng Nguyên Tố hoặc Kỹ Năng Nộ đánh trúng kẻ địch, sẽ nhận hiệu quả \"Thương Mến Của Gió Và Bài Ca Chăn Cừu\" trong 6s: Tấn Công tăng 25%. Nếu người trang bị đã hoàn thành Bài Tập Của Ma Nữ, \"Thương Mến Của Gió Và Bài Ca Chăn Cừu\" sẽ được nâng cấp thành \"Quyết Tâm Của Gió Và Bài Ca Chăn Cừu\", tăng thêm 20% Tỷ Lệ Bạo Kích cho người trang bị vượt qua thử thách. Người trang bị không ra trận cũng có thể kích hoạt hiệu quả nêu trên.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15044_4.webp" },
    { "id": "15045", "nameEn": "Celestial Gift", "nameVi": "Phước Lành Trời Cao", "rarityList": [4, 5], "piece2DescEn": "Energy Recharge +20%.", "piece2DescVi": "Hiệu Quả Nạp Nguyên Tố tăng 20%.", "piece4DescEn": "If the equipping character has completed Witch's Homework, after they use an Elemental Skill, they gain \"Light's Guidance\" for 20s: All nearby party members gain a 20% Elemental DMG Bonus corresponding to the equipping character's Elemental Type. The equipping character can trigger this effect while off-field. DMG Bonuses provided by Artifact Sets with the same name do not stack.\\n· When your party has the Hexerei: Secret Rite effect, Light's Guidance is upgraded to \"Mortal Hymn\": All nearby party members gain a 40% Elemental DMG Bonus corresponding to both the equipping character and the current active party member's Elemental Type instead. If both characters have the same Elemental Type, these bonuses will not stack.", "piece4DescVi": "Nếu người trang bị đã hoàn thành Bài Tập Của Ma Nữ, thì sau khi thi triển Kỹ Năng Nguyên Tố sẽ nhận được hiệu quả \"Thiên Quang Chỉ Dẫn\": Căn cứ vào Loại Nguyên Tố của người trang bị, khiến tất cả nhân vật trong đội ở gần nhận 20% buff Sát Thương Nguyên Tố tương ứng, duy trì 20s. Người trang bị không ra trận cũng có thể kích hoạt hiệu quả nêu trên. Hiệu quả tăng sát thương sản sinh từ bộ Thánh Di Vật cùng tên sẽ không thể cộng dồn.\\nKhi đội ngũ có hiệu ứng \"Hexerei - Nghi Thức Bí Mật\": Hiệu quả \"Thiên Quang Chỉ Dẫn\" nâng cấp thành \"Khúc Ca Phàm Trần\": Ngoài Loại Nguyên Tố của người trang bị, sẽ còn căn cứ vào Loại Nguyên Tố của nhân vật ra trận hiện tại trong đội bản thân, khiến tất cả nhân vật trong đội ở gần nhận buff Sát Thương Nguyên Tố tương ứng, đồng thời cả hai loại buff Sát Thương Nguyên Tố kể trên tăng đến 40%. Buff sát thương cho cùng loại nguyên tố sẽ không thể cộng dồn.", "iconUrl": "/assets/artifacts/UI_RelicIcon_15045_4.webp" },
    { "id": "15046", "nameEn": "Disenchantment in Deep Shadow", "nameVi": "Ảo Tưởng Vụn Vỡ Trong Bóng Tối", "rarityList": [4, 5], "piece2DescEn": "ATK +18%.", "piece2DescVi": "Tấn Công tăng 18%.", "piece4DescEn": "Increases Superconduct Reaction DMG by 80%. When the equipping character attacks opponents affected by Superconduct, this attack's CRIT Rate is increased by 16%. An all-new blessing may be obtained as you make your way toward Snezhnaya...", "piece4DescVi": "Sát thương phản ứng Siêu Dẫn tăng 80%. Khi người trang bị tấn công kẻ địch bị ảnh hưởng bởi phản ứng Siêu Dẫn, lần tấn công này tăng 16% Tỷ Lệ Bạo Kích. Trên đường đến Snezhnaya, có lẽ sẽ nhận được sự chúc phúc hoàn toàn mới...", "iconUrl": "/assets/artifacts/UI_RelicIcon_15046_4.webp" }
];
